 @Override void openPublic(String title,String url){if(url==null||!url.startsWith("https://")){toast("HTTPS link unavailable");return;}page(title);fillWorkspace();LinearLayout row=toolsBar();tool(row,"Library",()->watchExplore());tool(row,"Retry",()->openPublic(title,url));tool(row,"Browser",()->browser(url));providerStatus=paperText("Loading / provider playback and account controls stay on its page",14,MUTE);body.addView(providerStatus);final TextView status=providerStatus;final WebView site=new WebView(this);web=site;WebSettings settings=site.getSettings();settings.setJavaScriptEnabled(true);settings.setDomStorageEnabled(true);settings.setAllowFileAccess(false);settings.setAllowContentAccess(false);settings.setGeolocationEnabled(false);settings.setMediaPlaybackRequiresUserGesture(true);if(Build.VERSION.SDK_INT>=21)settings.setMixedContentMode(WebSettings.MIXED_CONTENT_NEVER_ALLOW);site.setWebChromeClient(new WebChromeClient());SiteClient client=Build.VERSION.SDK_INT>=23?new ModernSiteClient(site,status):new SiteClient(site,status);site.setWebViewClient(client);body.addView(site,new LinearLayout.LayoutParams(-1,0,1));int stamp=revision;ui.postDelayed(()->{if(stamp==revision&&web==site&&!client.finished&&!client.failed)status.setText("Not loaded. Retry or open in browser.");},25000);site.loadUrl(url);normalWindow();}
 class SiteClient extends WebViewClient {final WebView site;final TextView status;boolean failed=false,finished=false;SiteClient(WebView v,TextView t){site=v;status=t;}void unavailable(){failed=true;if(web==site)status.setText("Unavailable. Retry or open in browser.");}public boolean shouldOverrideUrlLoading(WebView v,String url){return !url.startsWith("https://");}public void onPageFinished(WebView v,String url){finished=true;if(web==site&&!failed)status.setText("Provider page loaded / video or live status not verified");}public void onReceivedError(WebView v,int code,String description,String url){if(url!=null&&url.equals(v.getUrl()))unavailable();}public void onReceivedSslError(WebView v,SslErrorHandler handler,android.net.http.SslError error){handler.cancel();unavailable();}}
