 class ResponsiveStudio extends Studio {boolean active=false;int pointer=-1;ResponsiveStudio(boolean colouring){super(colouring);setContentDescription("Drawing canvas fills the available workspace. Tools remain visible.");}void resizePaint(int w,int h){if(w<=0||h<=0)return;float factor=Math.min(1,1600f/Math.max(w,h));w=Math.max(1,Math.round(w*factor));h=Math.max(1,Math.round(h*factor));if(paintLayer.getWidth()==w&&paintLayer.getHeight()==h)return;Bitmap old=paintLayer,next=Bitmap.createBitmap(w,h,Bitmap.Config.ARGB_8888);Canvas c=new Canvas(next);float scale=Math.min(w/(float)old.getWidth(),h/(float)old.getHeight());float dx=(w-old.getWidth()*scale)/2,dy=(h-old.getHeight()*scale)/2;Matrix matrix=new Matrix();matrix.setScale(scale,scale);matrix.postTranslate(dx,dy);c.drawBitmap(old,matrix,new Paint(3));paintLayer=next;paintCanvas=c;old.recycle();}protected void onSizeChanged(int w,int h,int oldw,int oldh){super.onSizeChanged(w,h,oldw,oldh);resizePaint(w,h);}void undo(){super.undo();resizePaint(getWidth(),getHeight());invalidate();}void pageOutlines(Canvas c){float scale=Math.min(paintLayer.getWidth()/900f,paintLayer.getHeight()/560f);c.save();c.translate((paintLayer.getWidth()-900*scale)/2,(paintLayer.getHeight()-560*scale)/2);c.scale(scale,scale);outlines(c);c.restore();}protected void onDraw(Canvas c){c.drawColor(Color.WHITE);c.save();c.scale(getWidth()/(float)paintLayer.getWidth(),getHeight()/(float)paintLayer.getHeight());c.drawBitmap(paintLayer,0,0,null);pageOutlines(c);c.restore();}Bitmap export(){Bitmap result=Bitmap.createBitmap(paintLayer.getWidth(),paintLayer.getHeight(),Bitmap.Config.ARGB_8888);Canvas c=new Canvas(result);c.drawColor(Color.WHITE);c.drawBitmap(paintLayer,0,0,null);pageOutlines(c);return result;}public boolean onTouchEvent(MotionEvent e){if(getWidth()==0||getHeight()==0)return false;int action=e.getActionMasked();if(action==MotionEvent.ACTION_DOWN){if(history.size()>=4)history.removeFirst().recycle();history.add(paintLayer.copy(Bitmap.Config.ARGB_8888,true));pointer=e.getPointerId(0);active=true;getParent().requestDisallowInterceptTouchEvent(true);x=e.getX()*paintLayer.getWidth()/getWidth();y=e.getY()*paintLayer.getHeight()/getHeight();}if(action==MotionEvent.ACTION_CANCEL){active=false;getParent().requestDisallowInterceptTouchEvent(false);return true;}int index=e.findPointerIndex(pointer);if(!active||index<0)return true;pen.setColor(color);pen.setAlpha(alpha);pen.setStrokeWidth(width);pen.setStyle(Paint.Style.STROKE);pen.setStrokeCap(Paint.Cap.ROUND);pen.setXfermode(erase?new PorterDuffXfermode(PorterDuff.Mode.CLEAR):null);if(action==MotionEvent.ACTION_DOWN){pen.setStyle(Paint.Style.FILL);paintCanvas.drawCircle(x,y,width/2,pen);}else if(action==MotionEvent.ACTION_MOVE||action==MotionEvent.ACTION_UP){for(int n=0;n<=e.getHistorySize();n++){float nx=(n<e.getHistorySize()?e.getHistoricalX(index,n):e.getX(index))*paintLayer.getWidth()/getWidth(),ny=(n<e.getHistorySize()?e.getHistoricalY(index,n):e.getY(index))*paintLayer.getHeight()/getHeight();paintCanvas.drawLine(x,y,nx,ny,pen);x=nx;y=ny;}}if(action==MotionEvent.ACTION_UP||(action==MotionEvent.ACTION_POINTER_UP&&e.getPointerId(e.getActionIndex())==pointer)){active=false;getParent().requestDisallowInterceptTouchEvent(false);performClick();}invalidate();return true;}public boolean performClick(){super.performClick();return true;}}
 String encodeNote(CharSequence text){try{JSONObject value=new JSONObject().put("text",text.toString());JSONArray spans=new JSONArray();if(text instanceof Spanned){Spanned s=(Spanned)text;for(Object span:s.getSpans(0,s.length(),Object.class)){String kind=null;if(span instanceof StyleSpan){int style=((StyleSpan)span).getStyle();kind=style==Typeface.BOLD?"b":style==Typeface.ITALIC?"i":style==Typeface.BOLD_ITALIC?"bi":null;}else if(span instanceof UnderlineSpan)kind="u";else if(span instanceof RelativeSizeSpan)kind="h";if(kind!=null)spans.put(new JSONObject().put("k",kind).put("s",s.getSpanStart(span)).put("e",s.getSpanEnd(span)));}}return RICH+value.put("spans",spans).toString();}catch(Exception e){throw new IllegalStateException(e);}}
