 void historyNote(boolean redo){ArrayDeque<String> from=redo?redoNotes:undoNotes,to=redo?undoNotes:redoNotes;if(from.isEmpty()||noteText==null)return;String next=from.removeLast();to.addLast(encodeNote(noteText.getText()));try{replayingNote=true;noteText.setText(decodeNote(next));noteText.setSelection(noteText.length());}catch(Exception e){toast("Cannot restore editor step");}finally{replayingNote=false;}changedSchool();}
 void formatNote(String kind){if(noteText==null)return;int start=Math.max(0,noteText.getSelectionStart()),end=Math.max(start,noteText.getSelectionEnd());if(start==end){toast("Select text to format");return;}pushNote();Editable text=noteText.getText();Object span=kind.equals("b")?new StyleSpan(Typeface.BOLD):kind.equals("i")?new StyleSpan(Typeface.ITALIC):kind.equals("u")?new UnderlineSpan():new RelativeSizeSpan(1.35f);text.setSpan(span,start,end,Spanned.SPAN_EXCLUSIVE_EXCLUSIVE);changedSchool();}
