 @Override void flushSchool(){if(!dirty||noteId.isEmpty()||noteText==null||noteInk==null||noteRefs==null){super.flushSchool();return;}String id=noteId;JSONObject draft;try{draft=new JSONObject().put("id",id).put("notebook",noteClass).put("title",noteTitle.getText().toString()).put("section",noteSection.getText().toString()).put("body",encodeNote(noteText.getText())).put("ink",noteInk.model.json()).put("refs",noteRefs.toString());SQLiteDatabase database=db().getWritableDatabase();database.beginTransaction();try{super.flushSchool();if(dirty)throw new IOException("Base save failed");db().exec("UPDATE pages SET body=? WHERE id=?",draft.getString("body"),id);database.setTransactionSuccessful();}finally{database.endTransaction();}}catch(Exception e){dirty=true;try{unsaved.put(id,new JSONObject().put("id",id).put("notebook",noteClass).put("title",noteTitle.getText().toString()).put("section",noteSection.getText().toString()).put("body",encodeNote(noteText.getText())).put("ink",noteInk.model.json()).put("refs",noteRefs.toString()));}catch(Exception ignored){}if(savedStatus!=null)savedStatus.setText("NOT SAVED / keep app open and check storage");toast("School save failed");}}
 @Override void schoolSearch(){page("Search school notes");EditText query=field("Find words in titles or typed notes","",100);button("Search",()->{String term=query.getText().toString().trim().toLowerCase(Locale.getDefault());JSONArray pages=db().rows("SELECT p.id,p.title,p.body,p.section,n.name AS course FROM pages p JOIN notebooks n ON n.id=p.notebook ORDER BY p.updated DESC");page("School search results");int found=0;for(int i=0;i<pages.length()&&found<100;i++){JSONObject p=pages.optJSONObject(i);try{String words=p.optString("title")+"\n"+decodeNote(p.optString("body")).toString();if(words.toLowerCase(Locale.getDefault()).contains(term)){button(p.optString("course")+" / "+p.optString("title"),()->schoolNote(p.optString("id")));found++;}}catch(Exception ignored){}}text(found+" results / up to 100. Handwriting and PDF text are not searched.");button("Search again",()->schoolSearch());});}
